package com.taylordproductivty.med_timing_tracker.ui.components

import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.AlertDialog
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.OutlinedTextField
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.unit.dp
import com.taylordproductivty.med_timing_tracker.R
import com.taylordproductivty.med_timing_tracker.data.DoseLog

@Composable
fun EditDoseDialog(
    doseLog: DoseLog,
    medicationName: String,
    onDismiss: () -> Unit,
    onSave: (doseAmount: String, givenAtEpochMillis: Long) -> Unit,
) {
    var doseAmount by remember { mutableStateOf(doseLog.doseAmount) }
    var givenAtEpochMillis by remember { mutableStateOf(doseLog.givenAtEpochMillis) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.edit_dose_title)) },
        text = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Text(medicationName, style = MaterialTheme.typography.titleMedium)
                OutlinedTextField(
                    value = doseAmount,
                    onValueChange = { doseAmount = it },
                    label = { Text(stringResource(R.string.dose_given_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 16.dp),
                )
                TimeTakenField(
                    initialEpochMillis = givenAtEpochMillis,
                    onEpochMillisChange = { givenAtEpochMillis = it },
                    modifier = Modifier.padding(top = 16.dp),
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    if (doseAmount.isNotBlank()) {
                        onSave(doseAmount, givenAtEpochMillis)
                    }
                },
            ) {
                Text(stringResource(R.string.save))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
